$ErrorActionPreference='Stop';$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$Dir=Join-Path $Root 'frontend\src\apps\CloudOSFiles';$Target=Join-Path $Dir 'CloudOSFiles.tsx';if(-not(Test-Path (Join-Path $Root 'frontend\src\main.tsx'))){throw 'Execute na raiz do CloudOS-Unified.'};$Stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$Backup=Join-Path $Root "backup-files01-$Stamp";New-Item -ItemType Directory -Force $Backup|Out-Null;if(Test-Path $Dir){Copy-Item $Dir (Join-Path $Backup 'CloudOSFiles') -Recurse -Force};New-Item -ItemType Directory -Force $Dir|Out-Null;Copy-Item (Join-Path $Root 'payload\frontend\src\apps\CloudOSFiles\*') $Dir -Force;Push-Location $Root;try{& npm.cmd run lint;if($LASTEXITCODE){throw 'Lint falhou'};& npm.cmd run build;if($LASTEXITCODE){throw 'Build falhou'};& npm.cmd test;if($LASTEXITCODE){throw 'Testes falharam'};Write-Host "CloudOS Files instalado. Backup: $Backup" -ForegroundColor Green}catch{if(Test-Path (Join-Path $Backup 'CloudOSFiles')){Remove-Item $Dir -Recurse -Force;Copy-Item (Join-Path $Backup 'CloudOSFiles') $Dir -Recurse -Force};throw}finally{Pop-Location}
